(6068429, 893004, 106233, '<td valign="top">Too much processing, IMO</td>', 'Too much processing, IMO', '2010-06-23 23:35:14.000000', NULL, 1),
(6068436, 892424, 106233, '<td valign="top">I like the composition, but I think you pushed too much on the saturation.</td>', 'I like the composition, but I think you pushed too much on the saturation.', '2010-06-23 23:38:16.000000', NULL, 1),
(6068441, 892521, 40391, '<td valign="top">Came back for another look and didn''t agree with my original assessment and comment.  The focus still doesn''t work for me but it meets the challenge, I like the colours and lighting. Bumped to a 5.</td>', 'Came back for another look and didn''t agree with my original assessment and comment.  The focus still doesn''t work for me but it meets the challenge, I like the colours and lighting. Bumped to a 5.', '2010-06-23 23:44:49.000000', NULL, 1),
(6068443, 893113, 106233, '<td valign="top">The sky is well exposed, but the sun is too strong and distracting. Would be better to have avoided it. I would prefer if the lines of the building where leading to the center of the picture, and maybe starting on one of the  corners. Considering that this is a silhouette, you should have explored more the top of the building, trying to show more the "spikes" (don''t know the proper name) up there.</td>', 'The sky is well exposed, but the sun is too strong and distracting. Would be better to have avoided it. I would prefer if the lines of the building where leading to the center of the picture, and maybe starting on one of the  corners. Considering that this is a silhouette, you should have explored more the top of the building, trying to show more the "spikes" (don''t know the proper name) up there.', '2010-06-23 23:45:54.000000', NULL, 1),
(6068449, 893123, 106233, '<td valign="top">Very interesting composition, and very well exposed. Good choice to upside down.</td>', 'Very interesting composition, and very well exposed. Good choice to upside down.', '2010-06-23 23:48:33.000000', NULL, 1),
(6068453, 893106, 106233, '<td valign="top">i would like to see it as a dome on the bottom and middle of the frame, with the shadow line parallel to the frame.</td>', 'i would like to see it as a dome on the bottom and middle of the frame, with the shadow line parallel to the frame.', '2010-06-23 23:52:02.000000', NULL, 1),
(6068454, 892946, 106233, '<td valign="top">You achieved a very interesting movement. I think the tilt accentuates the curves of the fence.</td>', 'You achieved a very interesting movement. I think the tilt accentuates the curves of the fence.', '2010-06-23 23:53:48.000000', NULL, 1),
(6068455, 892463, 114285, '<td valign="top">Cool shot, don''t you just love Singapore :)</td>', 'Cool shot, don''t you just love Singapore :)', '2010-06-23 23:54:31.000000', NULL, 1),
(6068457, 892928, 106233, '<td valign="top">Nice vision!</td>', 'Nice vision!', '2010-06-23 23:55:08.000000', NULL, 1),
(6068458, 892391, 114285, '<td valign="top">Nice, shot, but I think you should''ve done a tighter crop, then it would''ve looked awesome:)</td>', 'Nice, shot, but I think you should''ve done a tighter crop, then it would''ve looked awesome:)', '2010-06-23 23:55:34.000000', NULL, 1),
(6068460, 893038, 106233, '<td valign="top">Very good! I had to tilt my head to catch it!</td>', 'Very good! I had to tilt my head to catch it!', '2010-06-23 23:56:16.000000', NULL, 1),
(6068461, 893106, 114285, '<td valign="top">Ha, I was going to do this, and the moon almost looked identical. Cool shot.</td>', 'Ha, I was going to do this, and the moon almost looked identical. Cool shot.', '2010-06-23 23:56:36.000000', NULL, 1),
(6068464, 892808, 106233, '<td valign="top">Simple and beautiful. The foreground is a little bit soft. Maybe zooming (or cropping) on the darker water would give more impact to it.</td>', 'Simple and beautiful. The foreground is a little bit soft. Maybe zooming (or cropping) on the darker water would give more impact to it.', '2010-06-23 23:58:16.000000', NULL, 1),
(6068465, 893065, 114285, '<td valign="top">Cool, top 10.</td>', 'Cool, top 10.', '2010-06-23 23:58:54.000000', NULL, 1),
(6068467, 892957, 106233, '<td valign="top">You got a very nice moment of the water and the clouds interacting with the rock... Now imagine if your picture where with the left frame parallel to the rock. I think it would have really improved.</td>', 'You got a very nice moment of the water and the clouds interacting with the rock... Now imagine if your picture where with the left frame parallel to the rock. I think it would have really improved.', '2010-06-24 00:01:42.000000', NULL, 1),
(6068544, 892345, 97270, '<td valign="top">If I can be honest,<br/> <br/>Pros:<br/>- the composition is good<br/>- the tilt adds value to the picture (I see the subject''s right hand and his posture is now aligned with a diagonal)<br/> <br/>Cons:<br/>- the background is too busy. That I think is hurting the image. The trees, the other person, take your attention away from the main subject.<br/> <br/>Hope that helps...good luck!</td>', 'If I can be honest, Pros:- the composition is good- the tilt adds value to the picture (I see the subject''s right hand and his posture is now aligned with a diagonal) Cons:- the background is too busy. That I think is hurting the image. The trees, the other person, take your attention away from the main subject. Hope that helps...good luck!', '2010-06-24 01:14:00.000000', NULL, 1),
(6068777, 892760, 118915, '<td valign="top">Extremely excellent art.</td>', 'Extremely excellent art.', '2010-06-24 12:02:27.000000', NULL, 1),
