(6069214, 892861, 23484, '<td valign="top">Excellent job on the diagonal.</td>', 'Excellent job on the diagonal.', '2010-06-24 22:35:47.000000', NULL, 1),
(6069215, 893034, 23484, '<td valign="top">Now those are some odd angles.</td>', 'Now those are some odd angles.', '2010-06-24 22:36:07.000000', NULL, 1),
