(6069226, 892919, 23484, '<td valign="top">Great angle and perfect exposure.</td>', 'Great angle and perfect exposure.', '2010-06-24 22:40:31.000000', NULL, 1),
(6069228, 893045, 23484, '<td valign="top">I love the grainy B&amp;W. Nice angle.</td>', 'I love the grainy B&W. Nice angle.', '2010-06-24 22:41:00.000000', NULL, 1),
(6069229, 892804, 23484, '<td valign="top">Nice capture and great perspective.</td>', 'Nice capture and great perspective.', '2010-06-24 22:41:23.000000', NULL, 1),
(6069230, 892987, 23484, '<td valign="top">Very nice point of view.</td>', 'Very nice point of view.', '2010-06-24 22:41:40.000000', NULL, 1),
(6069240, 893070, 23484, '<td valign="top">I like the opposite angles.</td>', 'I like the opposite angles.', '2010-06-24 22:51:19.000000', NULL, 1),
