(6069247, 893115, 23484, '<td valign="top">Cool idea.</td>', 'Cool idea.', '2010-06-24 22:56:10.000000', NULL, 1),
(6069273, 893002, 106233, '<td valign="top">Very good idea! Did you glued the ball?</td>', 'Very good idea! Did you glued the ball?', '2010-06-24 23:13:50.000000', NULL, 1),
(6069276, 893074, 106233, '<td valign="top">Good try, but you had some problem with the alignment. The lightning needed some improvement also. The picture is too flat.</td>', 'Good try, but you had some problem with the alignment. The lightning needed some improvement also. The picture is too flat.', '2010-06-24 23:16:16.000000', NULL, 1),
(6069283, 892827, 106233, '<td valign="top">The light is too harsh for this kind of picture, where you were not exactly exploring the shadows.</td>', 'The light is too harsh for this kind of picture, where you were not exactly exploring the shadows.', '2010-06-24 23:19:10.000000', NULL, 1),
(6069284, 892404, 106233, '<td valign="top">Very good! I would like to see all the reflection, though.</td>', 'Very good! I would like to see all the reflection, though.', '2010-06-24 23:20:01.000000', NULL, 1),
(6069287, 892564, 106233, '<td valign="top">Interesting concept, but i think you had some problems with distortion caused by the water (or by the water container that i suppose to exist)</td>', 'Interesting concept, but i think you had some problems with distortion caused by the water (or by the water container that i suppose to exist)', '2010-06-24 23:22:11.000000', NULL, 1),
(6069290, 893067, 106233, '<td valign="top">Very good composition and light. You also found an interesting floor to use (that looks like a wall). I just think that I would prefer to see her going up and not down. Maybe tilting to the other side would be better.</td>', 'Very good composition and light. You also found an interesting floor to use (that looks like a wall). I just think that I would prefer to see her going up and not down. Maybe tilting to the other side would be better.', '2010-06-24 23:24:12.000000', NULL, 1),
(6069296, 892000, 106233, '<td valign="top">I think it is over processed, and I don´t see the tilt.</td>', 'I think it is over processed, and I don´t see the tilt.', '2010-06-24 23:26:48.000000', NULL, 1),
